@OptIn(ExperimentalMaterial3Api::class)
@Composable fun HealthWorkspaceScreen(
  overviewState:LoadState<WorkspaceOverview>,recordsState:LoadState<RecordPage>,deviceStatus:DeviceSyncStatus,queueState:LoadState<QueueSummary>,samsungAvailable:Boolean,
  onRetry:()->Unit,onLoadMore:()->Unit,onBack:()->Unit,onDetail:(LifeDomain,String,String)->Unit,onCapture:(CaptureKind)->Unit,
  onHealthSync:()->Unit,onSamsungSync:()->Unit,onScale:()->Unit,onSettings:()->Unit,onMeals:()->Unit
){
  var tab by rememberSaveable{mutableStateOf("overview")}
  val overview=(overviewState as? LoadState.Ready)?.value as? WorkspaceOverview.Health
  Scaffold(containerColor=MaterialTheme.colorScheme.background,topBar={TopAppBar(
    title={Column{Text("健康");Text(healthSourceLine(overview),style=MaterialTheme.typography.labelMedium,color=healthSourceColor(overview))}},
    navigationIcon={IconButton(onClick=onBack){Text("‹",style=MaterialTheme.typography.headlineLarge)}},
    actions={IconButton(onClick=onSettings){Icon(Icons.Default.Settings,"健康数据与设备设置")}}
  )}){padding->
    LazyColumn(Modifier.fillMaxSize().padding(padding),contentPadding=PaddingValues(horizontal=20.dp,vertical=10.dp),verticalArrangement=Arrangement.spacedBy(18.dp)){
      item{Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(8.dp)){healthTabs.forEach{(key,label)->FilterChip(selected=tab==key,onClick={tab=key},label={Text(label)})};FilterChip(selected=false,onClick=onMeals,label={Text("饮食")})}}
      item{StateContent(overviewState,onRetry){} }
      if(overview!=null){
        when(tab){
          "body"->item{BodyMetricsWorkspace(overview.metrics,onDetail,onCapture)}
          "activity"->item{ActivityWorkspace(overview.history,onDetail,onCapture)}
          "sleep"->item{SleepWorkspace(overview.history)}
          else->{item{DailyActivityHero(overview.daily,onCapture)};item{HealthOverviewCards(overview,{tab=it},onMeals)};item{BodyCompositionStrip(overview.metrics){tab="body"}}}
        }
        item{CompactDeviceStatus(deviceStatus,queueState,samsungAvailable,onHealthSync,onSamsungSync,onScale,onSettings)}
      }
      if(tab=="overview"){
        item{Text("最近健康记录",style=MaterialTheme.typography.titleLarge)}
        item{StateContent(recordsState,onRetry){} }
        if(recordsState is LoadState.Ready){items(recordsState.value.items.take(8).size){index->val record=recordsState.value.items[index];RecordRow(record){onDetail(LifeDomain.Health,record.detailId?:record.id,record.title)}};if(recordsState.value.nextCursor!=null)item{TextButton(onClick=onLoadMore,Modifier.fillMaxWidth()){Text("加载更多健康记录")}}}
      }
      item{Spacer(Modifier.height(12.dp))}
    }
  }
}

@Composable private fun DailyActivityHero(daily:HealthDailyOverview?,onCapture:(CaptureKind)->Unit){HealthSurface{
  Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.Top){Column(Modifier.weight(1f)){Text("今日活动",style=MaterialTheme.typography.titleLarge);Text(daily?.occurredOn?:LocalDate.now().toString(),style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.onSurfaceVariant)};FilledTonalIconButton(onClick={onCapture(CaptureKind.Workout)}){Icon(Icons.Default.Add,"记录训练")}}
  Spacer(Modifier.height(12.dp));Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(18.dp)){TripleActivityRings(daily,Modifier.size(150.dp));Column(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(13.dp)){RingLegend("步数",daily?.steps?.toString()?:"—","步",ActivityGreen);RingLegend("活跃时间",daily?.activeMinutes?.toString()?:"—","分钟",ActivityBlue);RingLegend("活动热量",daily?.caloriesKcal?:"—","kcal",ActivityPurple)}}
  Text("圆环使用固定参考刻度：10,000 步、60 分钟、500 kcal；不是个人目标，也不补造缺失数据。",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)
}}

@Composable private fun TripleActivityRings(daily:HealthDailyOverview?,modifier:Modifier){
  val progress=listOf(((daily?.steps?:0L)/10_000f).coerceIn(0f,1f),((daily?.activeMinutes?:0L)/60f).coerceIn(0f,1f),((daily?.caloriesKcal?.toFloatOrNull()?:0f)/500f).coerceIn(0f,1f));val colors=listOf(ActivityGreen,ActivityBlue,ActivityPurple);val track=MaterialTheme.colorScheme.outline.copy(alpha=.24f)
  Box(modifier,contentAlignment=Alignment.Center){Canvas(Modifier.fillMaxSize()){colors.forEachIndexed{index,color->val inset=index*15.dp.toPx()+6.dp.toPx();val arcSize=Size(size.width-inset*2,size.height-inset*2);val stroke=Stroke(9.dp.toPx(),cap=StrokeCap.Round);drawArc(track,-90f,360f,false,Offset(inset,inset),arcSize,style=stroke);drawArc(color,-90f,360f*progress[index],false,Offset(inset,inset),arcSize,style=stroke)}};Column(horizontalAlignment=Alignment.CenterHorizontally){Text(daily?.workouts?.takeIf{it>0}?.toString()?:"—",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.SemiBold);Text("次运动",style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.onSurfaceVariant)}}
}

@Composable private fun RingLegend(label:String,value:String,unit:String,color:Color){Row(verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(9.dp).clip(CircleShape).background(color));Spacer(Modifier.width(9.dp));Column{Text(label,style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.onSurfaceVariant);Row(verticalAlignment=Alignment.Bottom){Text(value,style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.SemiBold);Spacer(Modifier.width(4.dp));Text(unit,style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.onSurfaceVariant)}}}}

@OptIn(ExperimentalLayoutApi::class)
@Composable private fun HealthOverviewCards(overview:WorkspaceOverview.Health,onTab:(String)->Unit,onMeals:()->Unit){LifeSection("今天一眼看懂"){FlowRow(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(10.dp),verticalArrangement=Arrangement.spacedBy(10.dp),maxItemsInEachRow=2){
  OverviewModule("睡眠",overview.daily?.sleepMinutes?.let(::minutesLabel)?:"尚未同步",overview.daily?.sleepSource?.let(::sourceLabel)?:"查看分期与近 7 天",SleepPurple,{onTab("sleep")},Modifier.weight(1f));val weight=overview.metrics.firstOrNull{it.key=="weight"}?.points?.lastOrNull();OverviewModule("身体",weight?.let{"${it.valueText} ${unitLabel(it.unit)}"}?:"尚未测量",weight?.occurredOn?:"体重与身体成分",BodyOrange,{onTab("body")},Modifier.weight(1f));OverviewModule("运动",overview.daily?.workouts?.takeIf{it>0}?.let{"$it 次"}?:"今日无记录","三星健康运动字段与名称",ActivityGreen,{onTab("activity")},Modifier.weight(1f));OverviewModule("饮食","餐照与营养","按早餐、午餐、晚餐查看",MealCoral,onMeals,Modifier.weight(1f))
}}}

@Composable private fun OverviewModule(title:String,value:String,note:String,tone:Color,onClick:()->Unit,modifier:Modifier=Modifier){Surface(modifier.heightIn(min=118.dp).clickable(role=Role.Button,onClick=onClick),shape=RoundedCornerShape(24.dp),color=MaterialTheme.colorScheme.surfaceVariant.copy(alpha=.48f)){Column(Modifier.padding(17.dp),verticalArrangement=Arrangement.spacedBy(7.dp)){Box(Modifier.width(28.dp).height(4.dp).clip(CircleShape).background(tone));Text(title,style=MaterialTheme.typography.labelLarge,color=MaterialTheme.colorScheme.onSurfaceVariant);Text(value,style=MaterialTheme.typography.titleLarge,maxLines=1,overflow=TextOverflow.Ellipsis);Text(note,style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant,maxLines=2)}}}

@Composable private fun BodyCompositionStrip(metrics:List<HealthMetricTrend>,onSelect:()->Unit){val visible=bodySnapshotMetrics(metrics);LifeSection("身体成分",action={TextButton(onClick=onSelect){Text("完整分析")}}){if(visible.none{it.points.isNotEmpty()})ChartEmpty("体脂秤或 Samsung Health 同步后，在这里形成身体成分卡片") else Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(10.dp)){visible.forEachIndexed{index,metric->val latest=metric.points.lastOrNull();Surface(Modifier.width(152.dp).clickable(role=Role.Button,onClick=onSelect),shape=RoundedCornerShape(22.dp),color=MaterialTheme.colorScheme.surfaceVariant.copy(alpha=.48f)){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(7.dp)){Text(metric.label,color=MaterialTheme.colorScheme.onSurfaceVariant,style=MaterialTheme.typography.labelLarge);Text(latest?.let{"${it.valueText} ${unitLabel(it.unit)}"}?:"未记录",style=MaterialTheme.typography.titleLarge,maxLines=1);MiniTrend(metric.points,Modifier.fillMaxWidth().height(48.dp),bodyTone(index));Text(latest?.sourceKind?.let(::sourceLabel)?:"等待同步",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}}}}}}

@Composable private fun BodyMetricsWorkspace(metrics:List<HealthMetricTrend>,onDetail:(LifeDomain,String,String)->Unit,onCapture:(CaptureKind)->Unit){
  var metricKey by rememberSaveable{mutableStateOf("weight")};var days by rememberSaveable{mutableIntStateOf(30)};val available=metrics.filter{!it.unavailable};val metric=available.firstOrNull{it.key==metricKey}?:available.firstOrNull();val cutoff=LocalDate.now().minusDays(days.toLong()-1);val shown=metric?.points.orEmpty().filter{runCatching{LocalDate.parse(it.occurredOn)>=cutoff}.getOrDefault(true)};val latest=shown.lastOrNull()?:metric?.points?.lastOrNull();val first=shown.firstOrNull();val average=shown.map{it.value}.average().takeUnless{it.isNaN()}
  Column(verticalArrangement=Arrangement.spacedBy(18.dp)){
    Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(8.dp)){available.forEach{item->FilterChip(metricKey==item.key,{metricKey=item.key},{Text(item.label)})}}
    HealthSurface(onClick=latest?.let{{onDetail(LifeDomain.Health,it.id,"${metric?.label}记录")}}){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.Top){Column(Modifier.weight(1f)){Text("${metric?.label?:"身体指标"}变化",style=MaterialTheme.typography.titleLarge);Text(latest?.let{"${it.valueText} ${unitLabel(it.unit)}"}?:"未记录",style=MaterialTheme.typography.headlineLarge,fontWeight=FontWeight.SemiBold);Text(latest?.let{"${it.occurredOn} · ${sourceLabel(it.sourceKind)}"}?:"等待设备同步或手动补记",color=MaterialTheme.colorScheme.onSurfaceVariant)};FilledTonalIconButton(onClick={onCapture(CaptureKind.Health)}){Icon(Icons.Default.Add,"添加记录")}};Row(horizontalArrangement=Arrangement.spacedBy(7.dp)){listOf(7,30,90).forEach{value->FilterChip(days==value,{days=value},{Text("$value 天")})}};if(shown.isEmpty())ChartEmpty("所选期间没有${metric?.label.orEmpty()}数据") else {TrendChart(shown,Modifier.fillMaxWidth().height(210.dp),BodyOrange);ChartDateRange(shown.first().occurredOn,shown.last().occurredOn)};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(12.dp)){SummaryFact("平均",average?.let{"${number(it)} ${latest?.unit?.let(::unitLabel).orEmpty()}"}?:"—",Modifier.weight(1f));SummaryFact("最低",shown.minOfOrNull{it.value}?.let{"${number(it)} ${latest?.unit?.let(::unitLabel).orEmpty()}"}?:"—",Modifier.weight(1f));SummaryFact("最高",shown.maxOfOrNull{it.value}?.let{"${number(it)} ${latest?.unit?.let(::unitLabel).orEmpty()}"}?:"—",Modifier.weight(1f))};if(first!=null&&latest!=null&&first.id!=latest.id)Text("期间变化 ${signed(latest.value-first.value)} ${unitLabel(latest.unit)} · ${shown.size} 个真实测量点",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}
    LifeSection("最近一次身体成分"){val snapshot=bodySnapshotMetrics(metrics);Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(10.dp)){snapshot.forEachIndexed{index,item->BodySnapshotCard(item,bodyTone(index)){item.points.lastOrNull()?.let{onDetail(LifeDomain.Health,it.id,"${item.label}记录")}}}}}
    LifeSection("测量历史"){if(shown.isEmpty())EmptyState("没有可显示的真实测量点") else shown.asReversed().take(12).forEach{point->Surface(Modifier.fillMaxWidth().clickable(role=Role.Button){onDetail(LifeDomain.Health,point.id,"${metric?.label}记录")},shape=RoundedCornerShape(18.dp),color=MaterialTheme.colorScheme.surfaceVariant.copy(alpha=.42f)){Row(Modifier.padding(15.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(point.occurredOn,style=MaterialTheme.typography.titleMedium);Text(sourceLabel(point.sourceKind),style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};Text("${point.valueText} ${unitLabel(point.unit)}",style=MaterialTheme.typography.titleMedium)}}};Text("变化只描述测量结果，不自动推断饮食、训练和体重之间的因果关系。",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}
  }
}

@Composable private fun BodySnapshotCard(metric:HealthMetricTrend,tone:Color,onClick:()->Unit){val latest=metric.points.lastOrNull();val previous=metric.points.dropLast(1).lastOrNull();Surface(Modifier.width(172.dp).heightIn(min=148.dp).clickable(role=Role.Button,onClick=onClick),shape=RoundedCornerShape(23.dp),color=tone.copy(alpha=.11f)){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text(metric.label,style=MaterialTheme.typography.labelLarge,color=tone);Text(latest?.let{"${it.valueText} ${unitLabel(it.unit)}"}?:"未记录",style=MaterialTheme.typography.titleLarge);Text(if(latest!=null&&previous!=null)"较上次 ${signed(latest.value-previous.value)} ${unitLabel(latest.unit)}" else latest?.occurredOn?:"等待同步",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant);MiniTrend(metric.points,Modifier.fillMaxWidth().height(44.dp),tone)}}}

@Composable private fun ActivityWorkspace(history:List<HealthDailyOverview>,onDetail:(LifeDomain,String,String)->Unit,onCapture:(CaptureKind)->Unit){
  var metric by rememberSaveable{mutableStateOf("steps")};val days=lastSevenDays(history);val workouts=history.flatMap{it.workoutItems}.sortedByDescending{it.startedAt?:it.occurredOn};val values=days.map{(_,day)->when(metric){"minutes"->day?.activeMinutes?.toDouble();"calories"->day?.caloriesKcal?.toDoubleOrNull();else->day?.steps?.toDouble()}};val total=values.filterNotNull().sum();val unit=when(metric){"minutes"->"分钟";"calories"->"kcal";else->"步"};val tone=when(metric){"minutes"->ActivityBlue;"calories"->ActivityPurple;else->ActivityGreen}
  Column(verticalArrangement=Arrangement.spacedBy(18.dp)){HealthSurface{Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.Top){Column(Modifier.weight(1f)){Text("近 7 天活动",style=MaterialTheme.typography.titleLarge);Text("已覆盖 ${values.count{it!=null}} 天 · 合计 ${number(total)} $unit",style=MaterialTheme.typography.bodyMedium,color=MaterialTheme.colorScheme.onSurfaceVariant)};FilledTonalButton(onClick={onCapture(CaptureKind.Workout)}){Text("记录运动")}};Row(horizontalArrangement=Arrangement.spacedBy(7.dp)){listOf("steps" to "步数","minutes" to "活跃时间","calories" to "活动热量").forEach{(key,label)->FilterChip(metric==key,{metric=key},{Text(label)})}};WeekBarChart(days.map{it.first},values,tone,Modifier.fillMaxWidth().height(180.dp))};LifeSection("运动记录"){Text("运动记录按 Samsung Health 的字段和命名习惯展示；经 Health Connect 聚合进入的数据会如实标注聚合来源，避免重复或伪装来源。",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant);if(workouts.isEmpty())ChartEmpty("近 7 天没有同步到运动明细") else workouts.forEach{workout->WorkoutCard(workout){onDetail(LifeDomain.Health,workout.id,"${workoutTypeUi(workout.sessionType)}记录")}}}}
}

@Composable private fun WorkoutCard(workout:HealthWorkoutSummary,onClick:()->Unit){val title=workoutTypeUi(workout.sessionType);val tone=workoutTone(workout.sessionType);HealthSurface(onClick=onClick){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.Top){Box(Modifier.size(48.dp).clip(CircleShape).background(tone.copy(alpha=.16f)),contentAlignment=Alignment.Center){Text(workoutGlyph(workout.sessionType),style=MaterialTheme.typography.titleLarge,color=tone)};Spacer(Modifier.width(13.dp));Column(Modifier.weight(1f)){Text(title,style=MaterialTheme.typography.titleLarge);Text("${workout.occurredOn}${workout.startedAt?.takeIf{it.length>=16}?.substring(11,16)?.let{" · $it"}.orEmpty()}",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};workout.sourceKind?.let{SourcePill(sourceLabel(it),tone)}};val facts=listOfNotNull(workout.distanceKm?.let{"距离" to "$it km"},workout.durationMinutes?.let{"时长" to minutesLabel(it)},workout.caloriesKcal?.let{"热量" to "$it kcal"},workout.heartRateAvg?.let{"平均心率" to "$it 次/分"});if(facts.isNotEmpty())Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(20.dp)){facts.forEach{(label,value)->HealthFact(label,value)}} else Text("三星记录未提供距离、时长、热量或心率明细。",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}}

@Composable private fun SleepWorkspace(history:List<HealthDailyOverview>){val days=lastSevenDays(history);val latest=history.lastOrNull{it.sleepMinutes!=null};val values=days.map{it.second?.sleepMinutes?.toDouble()?.div(60)};Column(verticalArrangement=Arrangement.spacedBy(18.dp)){HealthSurface{Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.Top){Column(Modifier.weight(1f)){Text("睡眠",style=MaterialTheme.typography.titleLarge);Text(latest?.occurredOn?:"昨晚",style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.onSurfaceVariant)};latest?.sleepSource?.let{SourcePill(sourceLabel(it),SleepPurple)}};Text(latest?.sleepMinutes?.let(::minutesLabel)?:"尚未同步",style=MaterialTheme.typography.displaySmall,fontWeight=FontWeight.SemiBold);SleepStageBar(latest);Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(18.dp)){HealthFact("深睡",latest?.deepMinutes?.let(::minutesLabel)?:"未提供");HealthFact("浅睡",latest?.lightMinutes?.let(::minutesLabel)?:"未提供");HealthFact("REM",latest?.remMinutes?.let(::minutesLabel)?:"未提供");HealthFact("清醒",latest?.awakeMinutes?.let(::minutesLabel)?:"未提供")};Text("设备没有提供的睡眠分期不会显示为 0，也不会根据时长臆造睡眠评分。",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};HealthSurface{Text("近 7 天睡眠",style=MaterialTheme.typography.titleLarge);Text("按 Samsung Health 日汇总展示实际睡眠时长",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant);WeekBarChart(days.map{it.first},values,SleepPurple,Modifier.fillMaxWidth().height(190.dp),"小时")}}}

@Composable private fun SleepStageBar(day:HealthDailyOverview?){val stages=listOf(day?.deepMinutes to Color(0xFF6257E8),day?.lightMinutes to Color(0xFF8C78F0),day?.remMinutes to Color(0xFFB991FF),day?.awakeMinutes to Color(0xFFFFA657));val total=stages.sumOf{it.first?:0L};Row(Modifier.fillMaxWidth().height(12.dp).clip(CircleShape)){if(total<=0)Box(Modifier.fillMaxSize().background(MaterialTheme.colorScheme.outline.copy(alpha=.25f))) else stages.forEach{(minutes,color)->if(minutes!=null&&minutes>0)Box(Modifier.weight(minutes.toFloat()).fillMaxHeight().background(color))}}}

@Composable private fun CompactDeviceStatus(status:DeviceSyncStatus,queueState:LoadState<QueueSummary>,samsungAvailable:Boolean,onHealthSync:()->Unit,onSamsungSync:()->Unit,onScale:()->Unit,onSettings:()->Unit){val queue=(queueState as? LoadState.Ready)?.value;LifeSection("设备与同步",action={TextButton(onClick=onSettings){Text("管理")}}){HealthSurface{SyncRow("Samsung Health",if(!samsungAvailable)"当前包未包含 SDK" else status.samsungMessage,status.samsungState,onSamsungSync);HorizontalDivider(color=MaterialTheme.colorScheme.outline.copy(alpha=.32f));SyncRow("小米体脂秤",status.scaleLastWeight?.let{"最近 $it kg · ${status.scaleMessage}"}?:status.scaleMessage,status.scaleState,onScale);HorizontalDivider(color=MaterialTheme.colorScheme.outline.copy(alpha=.32f));SyncRow("Health Connect","读取系统已授权的聚合健康数据","idle",onHealthSync);queue?.let{Text("离线队列：${it.waiting} 待发送 · ${it.reconciling} 核对中 · ${it.failed} 需处理",style=MaterialTheme.typography.bodySmall,color=if(it.failed>0)MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.onSurfaceVariant)}}}}

@Composable private fun SyncRow(title:String,subtitle:String,state:String,onClick:()->Unit){Row(Modifier.fillMaxWidth().clickable(role=Role.Button,onClick=onClick).padding(vertical=7.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(10.dp).clip(CircleShape).background(if(state in setOf("complete","committed","queued","detected"))ActivityGreen else if(state in setOf("error","timeout","needs_permission","needs_config"))MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.outline));Spacer(Modifier.width(11.dp));Column(Modifier.weight(1f)){Text(title,style=MaterialTheme.typography.titleMedium);Text(subtitle,style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant,maxLines=2,overflow=TextOverflow.Ellipsis)};Icon(Icons.Default.Refresh,"立即操作",tint=MaterialTheme.colorScheme.primary)}}

@OptIn(ExperimentalMaterial3Api::class)
@Composable fun MealsWorkspaceScreen(overviewState:LoadState<WorkspaceOverview>,recordsState:LoadState<RecordPage>,assetPreviews:Map<String,LoadState<ByteArray>>,onLoadAsset:(String)->Unit,onRetry:()->Unit,onLoadMore:()->Unit,onBack:()->Unit,onDetail:(LifeDomain,String,String)->Unit,onCapture:(CaptureKind)->Unit){
  var selectedDate by rememberSaveable{mutableStateOf(LocalDate.now().toString())};var query by rememberSaveable{mutableStateOf("")};val allRecords=(recordsState as? LoadState.Ready)?.value?.items.orEmpty().filter{it.meal!=null};val selected=allRecords.filter{it.meal?.occurredOn==selectedDate};val dates=(0L..6L).map{LocalDate.now().minusDays(it).toString()}.reversed()+listOf(selectedDate);val records=allRecords.filter{record->query.isBlank()||listOf(record.title,record.meal?.note.orEmpty(),mealTypeUi(record.meal?.mealType.orEmpty())).any{it.contains(query.trim(),ignoreCase=true)}};val nutrition=mealNutrition(selected)
  Scaffold(containerColor=MaterialTheme.colorScheme.background,topBar={TopAppBar(title={Column{Text("饮食");Text("餐次、餐照与真实营养汇总",style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.onSurfaceVariant)}},navigationIcon={IconButton(onClick=onBack){Text("‹",style=MaterialTheme.typography.headlineLarge)}},actions={FilledTonalIconButton(onClick={onCapture(CaptureKind.Meal)}){Icon(Icons.Default.Add,"记一餐")}})}){padding->LazyColumn(Modifier.fillMaxSize().padding(padding),contentPadding=PaddingValues(horizontal=20.dp,vertical=10.dp),verticalArrangement=Arrangement.spacedBy(18.dp)){
    item{DateNavigator(selectedDate,{selectedDate=it},dates.distinct())};item{MealNutritionHero(selectedDate,selected,nutrition,onCapture)};item{MealWeekCard(allRecords)};item{MealDayGroups(selected,assetPreviews,onLoadAsset,onDetail,onCapture)}
    val planning=(overviewState as? LoadState.Ready)?.value as? WorkspaceOverview.Meals
    if(planning!=null)item{LifeSection("餐单与采购"){HealthSurface{Text("${planning.mealPlans} 份餐单 · ${planning.shoppingLists} 张购物清单",style=MaterialTheme.typography.titleMedium);Text(if(planning.openShoppingItems==0)"当前没有待采购食材" else "${planning.openShoppingItems} 项食材待采购",color=MaterialTheme.colorScheme.onSurfaceVariant)}}}
    item{LifeSection("查找饮食记录"){OutlinedTextField(query,{query=it},Modifier.fillMaxWidth(),singleLine=true,placeholder={Text("搜索食物、餐次或备注")},leadingIcon={Icon(Icons.Default.Search,null)});if(query.isNotBlank())Text("匹配 ${records.size} 条",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)}};item{Text("最近记录",style=MaterialTheme.typography.titleLarge)};item{StateContent(recordsState,onRetry){} }
    if(recordsState is LoadState.Ready){items(records.size){index->val record=records[index];MealHistoryRow(record,assetPreviews,onLoadAsset){onDetail(LifeDomain.Meals,record.detailId?:record.id,record.title)}};if(records.isEmpty()&&query.isNotBlank())item{EmptyState("已加载记录中没有匹配内容")};if(recordsState.value.nextCursor!=null)item{TextButton(onClick=onLoadMore,Modifier.fillMaxWidth()){Text("加载更早记录")}}};item{Spacer(Modifier.height(12.dp))}
  }}
}

@Composable private fun DateNavigator(selected:String,onSelect:(String)->Unit,dates:List<String>){Column(verticalArrangement=Arrangement.spacedBy(10.dp)){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){OutlinedButton(onClick={onSelect(runCatching{LocalDate.parse(selected).minusDays(1).toString()}.getOrDefault(selected))}){Text("‹")};Column(Modifier.weight(1f),horizontalAlignment=Alignment.CenterHorizontally){Text(if(selected==LocalDate.now().toString())"今天" else selected,style=MaterialTheme.typography.titleLarge);Text(selected,color=MaterialTheme.colorScheme.onSurfaceVariant,style=MaterialTheme.typography.labelMedium)};OutlinedButton(onClick={onSelect(runCatching{LocalDate.parse(selected).plusDays(1).coerceAtMost(LocalDate.now()).toString()}.getOrDefault(selected))},enabled=selected<LocalDate.now().toString()){Text("›")}};Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(7.dp)){dates.forEach{date->FilterChip(selected==date,{onSelect(date)},{Text(if(date==LocalDate.now().toString())"今天" else date.takeLast(5))})}}}}

private data class MealNutrition(val kcal:Double,val protein:Double,val fat:Double,val carb:Double,val knownItems:Int,val totalItems:Int,val estimated:Boolean)
private fun mealNutrition(records:List<RecordSummary>):MealNutrition{val foods=records.flatMap{it.meal?.foods.orEmpty()};return MealNutrition(foods.sumOf{it.energyKcal?.toDoubleOrNull()?:0.0},foods.sumOf{it.proteinG?.toDoubleOrNull()?:0.0},foods.sumOf{it.fatG?.toDoubleOrNull()?:0.0},foods.sumOf{it.carbG?.toDoubleOrNull()?:0.0},foods.count{it.energyKcal!=null||it.proteinG!=null||it.fatG!=null||it.carbG!=null},foods.size,foods.any{it.estimated})}

