@Composable private fun TrendChart(points:List<HealthTrendPoint>,modifier:Modifier,color:Color){
  val values=points.map{it.value};val outline=MaterialTheme.colorScheme.outline;val surface=MaterialTheme.colorScheme.surface
  Canvas(modifier){
    val left=6.dp.toPx();val right=size.width-6.dp.toPx();val top=12.dp.toPx();val bottom=size.height-12.dp.toPx()
    repeat(4){index->val y=top+(bottom-top)*index/3f;drawLine(outline.copy(alpha=.35f),Offset(left,y),Offset(right,y),1.dp.toPx())}
    if(values.isEmpty())return@Canvas
    val min=values.minOrNull()?:0.0;val max=values.maxOrNull()?:min;val range=(max-min).takeIf{abs(it)>.000001}?:1.0
    fun pointOffset(index:Int,value:Double):Offset{
      val x=if(values.size==1)(left+right)/2 else left+(right-left)*index/values.lastIndex.toFloat()
      return Offset(x,bottom-(bottom-top)*((value-min)/range).toFloat())
    }
    if(values.size>1){val path=Path();values.forEachIndexed{index,value->val point=pointOffset(index,value);if(index==0)path.moveTo(point.x,point.y) else path.lineTo(point.x,point.y)};drawPath(path,color,style=Stroke(3.dp.toPx(),cap=StrokeCap.Round))}
    values.forEachIndexed{index,value->val point=pointOffset(index,value);drawCircle(surface,5.dp.toPx(),point);drawCircle(color,3.dp.toPx(),point)}
  }
}

@Composable private fun WeekBarChart(dates:List<LocalDate>,values:List<Double?>,color:Color,modifier:Modifier,unit:String?=null){val outline=MaterialTheme.colorScheme.outline;Column{Canvas(modifier){val maxValue=(values.filterNotNull().maxOrNull()?:0.0).coerceAtLeast(1.0);val gap=8.dp.toPx();val slot=(size.width-gap*(values.size-1))/values.size.coerceAtLeast(1);values.forEachIndexed{index,value->val left=index*(slot+gap);drawRoundRect(outline.copy(alpha=.2f),Offset(left,0f),Size(slot,size.height),cornerRadius=androidx.compose.ui.geometry.CornerRadius(slot/2));if(value!=null){val height=(size.height*(value/maxValue).toFloat()).coerceAtLeast(5.dp.toPx());drawRoundRect(color,Offset(left,size.height-height),Size(slot,height),cornerRadius=androidx.compose.ui.geometry.CornerRadius(slot/2))}}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){dates.forEachIndexed{index,date->Column(horizontalAlignment=Alignment.CenterHorizontally){Text(dayUi(date),style=MaterialTheme.typography.labelSmall,color=MaterialTheme.colorScheme.onSurfaceVariant);values.getOrNull(index)?.let{Text(number(it),style=MaterialTheme.typography.labelSmall,color=color)}}}}}}
