private fun unitLabel(value:String)=mapOf("level" to "级","kcal/day" to "kcal/天","bpm" to "次/分")[value.lowercase()]?:value
private fun workoutTypeUi(value:String):String{val key=value.trim().lowercase().replace(' ','_').replace('-','_');return mapOf("walking" to "步行","brisk_walking" to "健走","running" to "跑步","jogging" to "慢跑","treadmill" to "跑步机","treadmill_running" to "跑步机跑步","running_treadmill" to "跑步机跑步","walking_treadmill" to "跑步机步行","cycling" to "骑行","biking" to "骑行","stationary_biking" to "室内骑行","indoor_cycling" to "室内骑行","hiking" to "徒步","swimming" to "游泳","pool_swimming" to "泳池游泳","open_water_swimming" to "公开水域游泳","strength_training" to "力量训练","weight_training" to "力量训练","weightlifting" to "举重","weight_machine" to "器械训练","circuit_training" to "循环训练","hiit" to "高强度间歇训练","rowing" to "划船","rowing_machine" to "划船机","elliptical" to "椭圆机","stair_climbing" to "爬楼梯","yoga" to "瑜伽","pilates" to "普拉提","stretching" to "拉伸","dance" to "舞蹈","dancing" to "舞蹈","aerobics" to "有氧操","jump_rope" to "跳绳","football" to "足球","soccer" to "足球","basketball" to "篮球","badminton" to "羽毛球","tennis" to "网球","table_tennis" to "乒乓球","other" to "其他运动")[key]?:if(value.any{it.code>127})value else "其他运动 · ${value.replace('_',' ')}"}
